arguments.file_text:
@* Popup emoji picker with common emojis *@

<div class="emoji-picker">
    @foreach (var emoji in _emojis)
    {
        <button class="emoji-picker-btn" @onclick="() => OnEmojiSelected.InvokeAsync(emoji)" title="@emoji">
            @emoji
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<string> OnEmojiSelected { get; set; }

    private static readonly string[] _emojis = ["👍", "❤️", "😂", "🎉", "😮", "🚀"];
}

.emoji-picker {
    display: flex;
    gap: 2px;
    background: var(--bs-body-bg, #fff);
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 6px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.emoji-picker-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    padding: 4px 6px;
    cursor: pointer;
    border-radius: 4px;
    line-height: 1;
}

.emoji-picker-btn:hover {
    background-color: var(--bs-tertiary-bg, #f0f0f0);
}

@* Displays a row of reaction badges for a message *@

@if (Reactions?.Count > 0)
{
    <div class="reaction-bar">
        @foreach (var reaction in Reactions)
        {
            <button class="reaction-badge" @onclick="() => OnReactionClicked.InvokeAsync(reaction.Emoji)"
                    title="@string.Join(", ", reaction.Users)">
                <span class="reaction-emoji">@reaction.Emoji</span>
                <span class="reaction-count">@reaction.Users.Count</span>
            </button>
        }
    </div>
}

@code {
    [Parameter, EditorRequired]
    public List<Reaction>? Reactions { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnReactionClicked { get; set; }
}

.reaction-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    background: var(--bs-tertiary-bg, #f0f0f0);
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    line-height: 1.4;
}

.reaction-badge:hover {
    background: var(--bs-primary-bg-subtle, #cfe2ff);
    border-color: var(--bs-primary-border-subtle, #9ec5fe);
}

.reaction-emoji {
    font-size: 0.95rem;
}

.reaction-count {
    font-weight: 600;
    color: var(--bs-secondary-color, #6c757d);
}

@* Reusable message input with textarea and send/reply button *@

<div class="message-input-area">
    <textarea class="form-control message-textarea"
              placeholder="@Placeholder"
              @bind="_text"
              @onkeydown="HandleKeyDown"
              rows="2"></textarea>
    <button class="btn btn-primary send-btn" @onclick="Send" disabled="@string.IsNullOrWhiteSpace(_text)">
        @ButtonLabel
    </button>
</div>

@code {
    [Parameter]
    public string Placeholder { get; set; } = "Type a message…";

    [Parameter]
    public string ButtonLabel { get; set; } = "Send";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSubmit { get; set; }

    private string _text = string.Empty;

    private async Task Send()
    {
        if (string.IsNullOrWhiteSpace(_text)) return;
        var message = _text.Trim();
        _text = string.Empty;
        await OnSubmit.InvokeAsync(message);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Send();
        }
    }
}

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid var(--bs-border-color, #dee2e6);
    background: var(--bs-body-bg, #fff);
    align-items: flex-end;
}

.message-textarea {
    flex: 1;
    resize: none;
    font-size: 0.9rem;
}

.send-btn {
    white-space: nowrap;
    align-self: flex-end;
}

@* Popup emoji picker with common emojis *@

<div class="emoji-picker">
    @foreach (var emoji in _emojis)
    {
        <button class="emoji-picker-btn" @onclick="() => OnEmojiSelected.InvokeAsync(emoji)" title="@emoji">
            @emoji
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<string> OnEmojiSelected { get; set; }

    private static readonly string[] _emojis = ["👍", "❤️", "😂", "🎉", "😮", "🚀"];
}

