toolArgs.file_text:
.message-item {
    position: relative;
    padding: 8px 16px;
    border-bottom: 1px solid var(--bs-border-color-translucent, rgba(0,0,0,.05));
}

.message-item:hover {
    background-color: var(--bs-tertiary-bg, #f8f9fa);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: var(--bs-body-color);
}

.message-time {
    font-size: 0.75rem;
    color: var(--bs-secondary-color, #6c757d);
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.45;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-link {
    background: none;
    border: none;
    color: var(--bs-primary, #0d6efd);
    font-size: 0.8rem;
    padding: 2px 0;
    cursor: pointer;
    font-weight: 600;
    margin-top: 4px;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: 4px;
    right: 12px;
    display: flex;
    gap: 2px;
    background: var(--bs-body-bg, #fff);
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
}

.action-btn {
    background: none;
    border: none;
    font-size: 1rem;
    padding: 4px 6px;
    cursor: pointer;
    border-radius: 4px;
    line-height: 1;
}

.action-btn:hover {
    background-color: var(--bs-tertiary-bg, #f0f0f0);
}

.emoji-picker-container {
    position: absolute;
    top: 36px;
    right: 12px;
    z-index: 10;
}

