toolArgs.file_text:
@* Scrollable message list with load-more on scroll-to-top *@

<div class="message-list" @onscroll="HandleScroll" @ref="_scrollContainer">
    @if (IsLoadingMore)
    {
        <div class="loading-more text-center py-2">
            <span class="spinner-border spinner-border-sm" role="status"></span>
            Loading older messages…
        </div>
    }
    else if (HasMoreMessages)
    {
        <div class="text-center py-2">
            <button class="btn btn-sm btn-outline-secondary" @onclick="OnLoadMore">Load older messages</button>
        </div>
    }

    @foreach (var msg in Messages)
    {
        var summary = ThreadSummaries?.GetValueOrDefault(msg.Id);
        <MessageItem Message="msg"
                     IsThreadStarter="@(msg.ReplyToId == null && summary != null)"
                     ThreadReplyCount="@(summary?.ReplyCount ?? 0)"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, ThreadSummary>? ThreadSummaries { get; set; }

    [Parameter]
    public bool HasMoreMessages { get; set; }

    [Parameter]
    public bool IsLoadingMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference _scrollContainer;

    [Inject]
    private IJSRuntime JS { get; set; } = default!;

    private async Task HandleScroll()
    {
        if (!HasMoreMessages || IsLoadingMore) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            await OnLoadMore.InvokeAsync();
        }
    }
}

