    background-color: var(--bs-tertiary-bg, #f8f9fa);
}

.channel-item.active {
    background-color: var(--bs-primary-bg-subtle, #cfe2ff);
    border-left: 3px solid var(--bs-primary, #0d6efd);
}

.channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    color: var(--bs-body-color);
}

.unread-badge {
    font-size: 0.7rem;
    border-radius: 10px;
    min-width: 20px;
}

.channel-description {
    font-size: 0.75rem;
    color: var(--bs-secondary-color, #6c757d);
    margin-top: 2px;
    line-height: 1.3;
}

