@* Left sidebar showing list of channels *@

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h6 class="mb-0">Channels</h6>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="@(channel.Id == SelectedChannelId)"
                         OnSelected="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Channel> Channels { get; set; } = [];

    [Parameter]
    public int SelectedChannelId { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<int> OnChannelSelected { get; set; }
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: var(--bs-body-bg, #fff);
    border-right: 1px solid var(--bs-border-color, #dee2e6);
}

.sidebar-header {
    padding: 16px 14px 12px;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
    font-weight: 700;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
}

@* Main message area with header, message list, and input *@

<div class="message-area">
    @if (Channel != null)
    {
        <div class="area-header">
            <h6 class="mb-0"># @Channel.Name</h6>
            @if (!string.IsNullOrWhiteSpace(Channel.Description))
            {
                <span class="area-description">@Channel.Description</span>
            }
        </div>

        <MessageList Messages="Messages"
                     ThreadSummaries="ThreadSummaries"
                     HasMoreMessages="HasMoreMessages"
                     IsLoadingMore="IsLoadingMore"
                     OnLoadMore="OnLoadMore"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />

        <MessageInput Placeholder="@($"Message # {Channel.Name}")"
                      ButtonLabel="Send"
                      OnSubmit="OnSendMessage" />
    }
    else
    {
        <div class="no-channel-selected">
            <p class="text-secondary">Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter]
    public Channel? Channel { get; set; }

    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, ThreadSummary>? ThreadSummaries { get; set; }

    [Parameter]
    public bool HasMoreMessages { get; set; }

    [Parameter]
    public bool IsLoadingMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnSendMessage { get; set; }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: var(--bs-body-bg, #fff);
}

.area-header {
    padding: 14px 16px;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
    display: flex;
    align-items: baseline;
    gap: 12px;
}

.area-description {
    font-size: 0.8rem;
    color: var(--bs-secondary-color, #6c757d);
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

@* Right panel showing a message thread *@

<div class="thread-panel">
    <div class="thread-header">
        <h6 class="mb-0">Thread</h6>
        <button class="btn-close" @onclick="OnClose" aria-label="Close thread"></button>
    </div>

    @if (RootMessage != null)
    {
        <div class="thread-root-message">
            <div class="message-header">
                <span class="message-author">@RootMessage.Author</span>
                <span class="message-time">@RootMessage.SentAt.ToString("MMM d, h:mm tt")</span>
            </div>
            <div class="message-content">@RootMessage.Content</div>
        </div>

        <div class="thread-divider">
            <span>@ThreadMessages.Count @(ThreadMessages.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in ThreadMessages)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply in thread…"
                      ButtonLabel="Reply"
                      OnSubmit="OnReply" />
    }
</div>

@code {
    [Parameter]
    public Message? RootMessage { get; set; }

    [Parameter, EditorRequired]
    public List<Message> ThreadMessages { get; set; } = [];

    [Parameter, EditorRequired]
    public EventCallback OnClose { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

