@page "/chat"
@using sv_83a318b67e194899ac26e7fc760ce357.Components.Chat
@layout ChatLayout
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        SelectedChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_isThreadOpen ? "" : "chat-main-full")">
        <MessageArea Channel="_selectedChannel"
                     Messages="_messages"
                     ThreadSummaries="_threadSummaries"
                     HasMoreMessages="_hasMoreMessages"
                     IsLoadingMore="_isLoadingMore"
                     OnLoadMore="LoadMoreMessages"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage" />
    </div>

    @if (_isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    [Inject]
    private IChatService ChatService { get; set; } = default!;

    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<Message> _threadMessages = [];
    private Dictionary<int, ThreadSummary> _threadSummaries = [];
    private Channel? _selectedChannel;
    private int _selectedChannelId;
    private Message? _threadRootMessage;
    private bool _isThreadOpen;
    private bool _hasMoreMessages;
    private bool _isLoadingMore;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _threadSummaries = [];
        CloseThread();

        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = messages;
        _hasMoreMessages = messages.Count >= PageSize;

        await BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (_isLoadingMore || !_hasMoreMessages || _selectedChannel == null) return;

        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        _messages.InsertRange(0, older);
        _hasMoreMessages = older.Count >= PageSize;
        _isLoadingMore = false;

        await BuildThreadSummaries();
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel == null) return;

        var msg = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage == null) return;

        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _isThreadOpen = true;
    }

    private void CloseThread()
    {
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage == null || _selectedChannel == null) return;

        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootMessage.Id);
        _threadMessages.Add(reply);

        // Update thread summary
        _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(
            _threadRootMessage.Id,
            _threadMessages.Count,
            reply.SentAt
        );
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message's reactions
        var msg = _messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg != null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing != null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    private async Task BuildThreadSummaries()
    {
        _threadSummaries.Clear();
        // Identify thread starters: messages with no ReplyToId that have replies
        var rootIds = _messages.Where(m => m.ReplyToId == null).Select(m => m.Id).ToHashSet();
        var replyCounts = _messages
            .Where(m => m.ReplyToId != null && rootIds.Contains(m.ReplyToId.Value))
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in replyCounts)
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt)
            );
        }

        // Also check via GetThreadAsync for root messages without inline replies
        foreach (var rootId in rootIds)
        {
            if (!_threadSummaries.ContainsKey(rootId))
            {
                // We don't pre-fetch all threads—summaries are built from loaded messages only
                // Threads will show reply counts only when replies are in the loaded batch
            }
        }

        await Task.CompletedTask;
    }
}

.chat-container {
    display: flex;
    height: 100%;
    width: 100%;
    overflow: hidden;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    flex-shrink: 0;
}

.chat-main {
    width: 55%;
    flex-shrink: 0;
    flex-grow: 0;
}

.chat-main-full {
    width: 80%;
    flex-grow: 1;
}

.chat-thread {
    width: 25%;
    min-width: 250px;
    flex-shrink: 0;
}

.chat-layout {
    height: 100vh;
    width: 100vw;
    overflow: hidden;
    display: flex;
}

